{"command":"cat > query.go <<'EOF'
package main

import (
    "fmt"
    "strconv"
    "strings"
    "time"
)

var commandNames = []string{
    "next", "add", "rm", "remove", "template", "log", "start", "note", "notes", "stop", "done", "resolve", "context", "modify", "edit", "undo", "sync", "open", "git", "show-next", "show-projects", "show-tags", "show-active", "show-paused", "show-open", "show-resolved", "show-templates", "show-unorganised", "bash-completion", "fish-completion", "zsh-completion", "help", "version",
}

func canonicalCommand(s string) string {
    switch s {
    case "rm": return "remove"
    case "notes": return "note"
    case "resolve": return "done"
    case "show-next": return "next"
    }
    return s
}

func knownCommand(s string) bool {
    if s == "_completions" { return true }
    for _, c := range commandNames { if s == c { return true } }
    return false
}

// A query retains the distinction between selecting tasks and modifying them.
// Empty project/priority values deliberately do not constitute a constraint.
type Query struct {
    IDs []int
    Text string
    Notes string
    Tags []string
    AntiTags []string
    Project string
    AntiProjects []string
    Priority string
    Due time.Time
    HasDue bool
    Template int
    Ignore bool
}

func (q Query) operations() bool {
    return len(q.Tags)>0 || len(q.AntiTags)>0 || q.Project!="" || len(q.AntiProjects)>0 || q.Priority!="" || !q.Due.IsZero()
}
func (q Query) empty() bool {
    return !q.operations() && len(q.IDs)==0 && q.Text=="" && q.Template==0
}
func (q Query) String() string {
    p := []string{}
    for _, id := range q.IDs { p=append(p,strconv.Itoa(id)) }
    for _, t := range q.Tags { p=append(p,"+"+t) }
    for _, t := range q.AntiTags { p=append(p,"-"+t) }
    if q.Project!="" { p=append(p,"project:"+q.Project) }
    for _, t := range q.AntiProjects { p=append(p,"-project:"+t) }
    if !q.Due.IsZero() { p=append(p,"due:"+q.Due.Format("2006-01-02")) }
    if q.Priority!="" { p=append(p,q.Priority) }
    if q.Template!=0 { p=append(p,fmt.Sprintf("template:%d",q.Template)) }
    if q.Text!="" { p=append(p,strconv.Quote(q.Text)) }
    return strings.Join(p," ")
}

func parseInvocation(args []string) (string, []string, Query, error) {
    cmd := "next"
    rest := append([]string{},args...)
    for i, s := range rest {
        if s=="/" { break }
        lower:=strings.ToLower(s)
        if knownCommand(lower) {
            cmd=canonicalCommand(lower)
            rest=append(rest[:i],rest[i+1:]...)
            break
        }
    }
    // Commands with their own argument language must be passed through intact.
    if cmd=="git" || cmd=="undo" || cmd=="_completions" { return cmd,rest,Query{},nil }
    q,err:=parseQuery(rest)
    return cmd,rest,q,err
}

func parseQuery(args []string) (Query,error) {
    q:=Query{}
    before:=[]string{}
    for i,s:=range args {
        if s=="/" {
            q.Notes=strings.Join(args[i+1:]," ")
            break
        }
        if s=="--" { q.Ignore=true; continue }
        before=append(before,s)
    }
    i:=0
    for ;i<len(before);i++ {
        n,err:=strconv.Atoi(before[i])
        if err!=nil { break }
        q.IDs=append(q.IDs,n)
    }
    text:=[]string{}
    for _,s:=range before[i:] {
        lower:=strings.ToLower(s)
        switch {
        case strings.HasPrefix(lower,"due:"):
            if q.HasDue { return q,fmt.Errorf("Query should only have one due date") }
            q.HasDue=true
            d,err:=parseDue(strings.TrimPrefix(lower,"due:"))
            if err!=nil { return q,err }
            q.Due=d
        case strings.HasPrefix(lower,"template:"):
            q.Template,_=strconv.Atoi(strings.TrimPrefix(lower,"template:"))
        case strings.HasPrefix(lower,"project:") && q.Project=="":
            q.Project=strings.TrimPrefix(lower,"project:")
        case strings.HasPrefix(lower,"-project:"):
            q.AntiProjects=append(q.AntiProjects,strings.TrimPrefix(lower,"-project:"))
        case len(s)>1 && s[0]=='+':
            q.Tags=append(q.Tags,lower[1:])
        case len(s)>1 && s[0]=='-':
            q.AntiTags=append(q.AntiTags,lower[1:])
        case (s=="P0" || s=="P1" || s=="P2" || s=="P3") && q.Priority=="":
            q.Priority=s
        default:
            text=append(text,s)
        }
    }
    q.Text=strings.Join(text," ")
    return q,nil
}

func parseDue(s string) (time.Time,error) {
    now:=time.Now()
    today:=time.Date(now.Year(),now.Month(),now.Day(),0,0,0,0,time.Local)
    switch s {
    case "today": return today,nil
    case "tomorrow": return today.AddDate(0,0,1),nil
    case "yesterday": return today.AddDate(0,0,-1),nil
    }
    if len(s)==10 {
        if t,err:=time.Parse("2006-01-02",s);err==nil { return t,nil }
    }
    if len(s)==5 {
        if t,err:=time.Parse("01-02",s);err==nil {
            return time.Date(now.Year(),t.Month(),t.Day(),0,0,0,0,time.Local),nil
        }
    }
    if len(s)==1 || len(s)==2 {
        if t,err:=time.Parse("2",s);err==nil {
            return time.Date(now.Year(),now.Month(),t.Day(),0,0,0,0,time.Local),nil
        }
    }
    parts:=strings.Split(s,"-")
    weekday:=s
    if len(parts)==2 { weekday=parts[1] }
    if len(parts)<=2 {
        days:=[]string{"sunday","monday","tuesday","wednesday","thursday","friday","saturday"}
        for n,name:=range days {
            if weekday==name || weekday==name[:3] {
                delta:=n-int(now.Weekday())
                if len(parts)==1 { if delta<0 { delta+=7 } } else if parts[0]=="next" { if delta<=0 { delta+=7 } }
                return today.AddDate(0,0,delta),nil
            }
        }
    }
    return time.Time{},fmt.Errorf("Invalid due date format: %s\nExpected format: YYYY-MM-DD, MM-DD or DD, relative date like 'next-monday', 'today', etc.",s)
}

// Contexts supply constraints, but never descriptions, IDs, or templates.
func combineQuery(q, ctx Query) (Query,error) {
    if q.Ignore { return q,nil }
    if q.Project!="" && ctx.Project!="" && q.Project!=ctx.Project { return q,fmt.Errorf("Could not apply q2, project conflict") }
    if q.Priority!="" && ctx.Priority!="" && q.Priority!=ctx.Priority { return q,fmt.Errorf("Could not apply q2, priority conflict") }
    if !q.Due.IsZero() && !ctx.Due.IsZero() && !q.Due.Equal(ctx.Due) { return q,fmt.Errorf("Could not apply q2, date filter conflict") }
    if q.Project=="" { q.Project=ctx.Project }
    if q.Priority=="" { q.Priority=ctx.Priority }
    if q.Due.IsZero() { q.Due=ctx.Due }
    q.Tags=append(append([]string{},q.Tags...),ctx.Tags...)
    q.AntiTags=append(append([]string{},q.AntiTags...),ctx.AntiTags...)
    q.AntiProjects=append(append([]string{},q.AntiProjects...),ctx.AntiProjects...)
    return q,nil
}
EOF
cat > task.go <<'EOF'
package main

import (
    "crypto/rand"
    "fmt"
    "sort"
    "strings"
    "time"
)

type Task struct {
    UUID string `json:"uuid"`
    Status string `json:"status"`
    ID int `json:"id"`
    Summary string `json:"summary"`
    Notes string `json:"notes"`
    Tags []string `json:"tags"`
    Project string `json:"project"`
    Priority string `json:"priority"`
    Created time.Time `json:"created"`
    Resolved time.Time `json:"resolved"`
    Due time.Time `json:"due"`
    DelegatedTo string `json:"-"`
    Subtasks []string `json:"-"`
    Dependencies []string `json:"-"`
    path string
}

func newUUID() string {
    b:=make([]byte,16)
    if _,err:=rand.Read(b);err!=nil { panic(err) }
    b[6]=(b[6]&0x0f)|0x40
    b[8]=(b[8]&0x3f)|0x80
    return fmt.Sprintf("%x-%x-%x-%x-%x",b[:4],b[4:6],b[6:8],b[8:10],b[10:])
}
func uniqueTags(tags []string) []string {
    set:=make(map[string]bool)
    for _,tag:=range tags { set[tag]=true }
    out:=make([]string,0,len(set))
    for tag:=range set { out=append(out,tag) }
    sort.Strings(out)
    return out
}
func createTask(q Query,status string) *Task {
    p:=q.Priority
    if p=="" { p="P2" }
    return &Task{UUID:newUUID(),Status:status,Summary:q.Text,Notes:q.Notes,Tags:uniqueTags(q.Tags),Project:q.Project,Priority:p,Due:q.Due,Created:time.Now(),Subtasks:[]string{},Dependencies:[]string{}}
}
func (t *Task) label() string {
    if t.ID==0 { return t.Summary }
    return fmt.Sprintf("%d: %s",t.ID,t.Summary)
}
