package main

import (
    "encoding/json"
    "fmt"
    "regexp"
    "strconv"
    "strings"
    "time"
    "unicode"
)

// The data files are simple YAML records. This reader accepts both block and
// flow lists, quoted scalars, and literal/folded notes, including hand-edited
// records. Unknown keys remain harmless to the command-line data model.
func readTaskYAML(data []byte) (*Task,error) {
    t:=&Task{Priority:"P2",Created:time.Now()}
    s:=strings.TrimPrefix(string(data),"\ufeff")
    if strings.HasPrefix(strings.TrimSpace(s),"{") {
        var m map[string]interface{}
        if err:=json.Unmarshal(data,&m);err!=nil { return nil,err }
        var b strings.Builder
        for key,val:=range m {
            switch v:=val.(type) {
            case string: b.WriteString(yamlField(key,v))
            case []interface{}:
                b.WriteString(key+":\n")
                for _,it:=range v { b.WriteString("- "+yamlScalar(fmt.Sprint(it))+"\n") }
            }
        }
        s=b.String()
    }
    lines:=strings.Split(s,"\n")
    for i:=0;i<len(lines);i++ {
        line:=strings.TrimSuffix(lines[i],"\r")
        if strings.TrimSpace(line)=="" || strings.HasPrefix(strings.TrimSpace(line),"#") || line=="---" || line=="..." { continue }
        if len(line)>0 && (line[0]==' ' || line[0]=='\t') { continue }
        split:=strings.Index(line,":")
        if split<0 { return nil,fmt.Errorf("yaml: line %d: could not find expected ':'",i+1) }
        key:=strings.TrimSpace(line[:split])
        raw:=strings.TrimSpace(line[split+1:])
        val:=""
        var list []string
        if strings.HasPrefix(raw,"|") || strings.HasPrefix(raw,">") {
            folded:=raw[0]=='>'
            indent:=0
            body:=[]string{}
            for j:=i+1;j<len(lines);j++ {
                x:=strings.TrimSuffix(lines[j],"\r")
                if j==len(lines)-1 && x=="" { break }
                if strings.TrimSpace(x)!="" && len(x)>0 && x[0]!=' ' && x[0]!='\t' { break }
                if strings.TrimSpace(x)!="" && indent==0 {
                    indent=len(x)-len(strings.TrimLeft(x," "))
                }
                body=append(body,x)
                i=j
            }
            for j,x:=range body {
                n:=indent
                if len(x)<n { n=len(x) }
                if strings.TrimSpace(x)=="" { body[j]="" } else { body[j]=x[n:] }
            }
            val=strings.Join(body,"\n")
            if len(body)>0 { val+="\n" }
            if folded {
                x:=strings.Split(val,"\n"); var out strings.Builder
                for j,line:=range x {
                    out.WriteString(line)
                    if j<len(x)-1 {
                        if line!="" && x[j+1]!="" { out.WriteByte(' ') } else { out.WriteByte('\n') }
                    }
                }
                val=out.String()
            }
            if strings.Contains(raw,"-") { val=strings.TrimRight(val,"\n") } else if !strings.Contains(raw,"+") { if val!="" { val=strings.TrimRight(val,"\n")+"\n" } }
        } else if strings.HasPrefix(raw,"[") {
            var err error
            list,err=parseFlowList(raw)
            if err!=nil { return nil,err }
        } else if raw=="" {
            for i+1<len(lines) {
                x:=strings.TrimSpace(lines[i+1])
                if !strings.HasPrefix(x,"- ") && x!="-" { break }
                v,err:=parseYAMLScalar(strings.TrimSpace(x[1:]))
                if err!=nil { return nil,err }
                list=append(list,v)
                i++
            }
        } else {
            var err error
            val,err=parseYAMLScalar(raw)
            if err!=nil { return nil,err }
            // Plain and quoted scalars can be continued on indented lines.
            for i+1<len(lines) {
                x:=lines[i+1]
                if len(x)==0 || x[0]!=' ' { break }
                x=strings.TrimSpace(x)
                if x!="" { val+=" "+x }
                i++
            }
        }
        switch strings.ToLower(key) {
        case "status": t.Status=val
        case "summary": t.Summary=val
        case "notes": t.Notes=val
        case "tags": t.Tags=list
        case "project": t.Project=val
        case "priority": if val!="" { t.Priority=val }
        case "delegatedto": t.DelegatedTo=val
        case "subtasks": t.Subtasks=list
        case "dependencies": t.Dependencies=list
        case "created","resolved","due":
            if val=="" { continue }
            tm,err:=parseFileTime(val)
            if err!=nil { return nil,err }
            if key=="created" { t.Created=tm } else if key=="resolved" { t.Resolved=tm } else { t.Due=tm }
        }
    }
    return t,nil
}

func parseFileTime(s string) (time.Time,error) {
    for _,layout:=range []string{time.RFC3339Nano,"2006-01-02","2006-01-02 15:04:05Z07:00","2006-01-02 15:04:05"} {
        if t,e:=time.Parse(layout,s);e==nil{return t,nil}
    }
    _,e:=time.Parse(time.RFC3339Nano,s)
    return time.Time{},e
}
func parseYAMLScalar(s string)(string,error) {
    s=strings.TrimSpace(s)
    if s=="null" || s=="~" || s=="Null" || s=="NULL" { return "",nil }
    if strings.HasPrefix(s,"!!str ") { s=strings.TrimSpace(s[6:]) }
    if strings.HasPrefix(s,"\"") {
        // JSON/Go string escapes cover the common YAML quoted representation.
        end:=len(s)
        escaped:=false
        for i:=1;i<len(s);i++ {
