            if s[i]=='\\' && !escaped { escaped=true } else { escaped=false }
        }
        v,e:=strconv.Unquote(s[:end]);return v,e
    }
    if strings.HasPrefix(s,"'") {
        if !strings.HasSuffix(s,"'") || len(s)<2 { return "",fmt.Errorf("yaml: did not find expected key") }
        return strings.ReplaceAll(s[1:len(s)-1],"''","'"),nil
    }
    if i:=strings.Index(s," #");i>=0 { s=s[:i] }
    return s,nil
}
func parseFlowList(s string)([]string,error) {
    end:=strings.LastIndex(s,"]")
    if end<0 { return nil,fmt.Errorf("yaml: did not find expected ',' or ']'") }
    s=s[1:end]
    out:=[]string{}
    quote:=byte(0);last:=0;escaped:=false
    for i:=0;i<=len(s);i++ {
        if i==len(s) || (s[i]==',' && quote==0) {
            if strings.TrimSpace(s[last:i])!="" { v,e:=parseYAMLScalar(s[last:i]);if e!=nil{return nil,e};out=append(out,v) }
            last=i+1;continue
        }
        if quote!=0 {
            if s[i]==quote && !escaped { quote=0 }
            if s[i]=='\\' && !escaped { escaped=true } else { escaped=false }
        } else if s[i]=='\'' || s[i]=='"' { quote=s[i] }
    }
    return out,nil
}

var numericYAML=regexp.MustCompile(`^[+-]?(?:[0-9][0-9_]*(?:\.[0-9_]*)?(?:[eE][+-]?[0-9]+)?|\.[0-9]+|0[xX][0-9a-fA-F_]+|0[bB][01_]+)$`)
