const reset="\x1b[0m"
const grey="\x1b[38;5;245m"
const red="\x1b[31m"
var openStatuses=[]string{"active","pending","paused"}

func main() {
    if err:=run(os.Args[1:]);err!=nil {
        fmt.Fprintln(os.Stderr,red+err.Error()+reset)
        os.Exit(1)
    }
}
func printHelp(topic string) {
    topic=canonicalCommand(topic)
    b,e:=textFiles.ReadFile("cli_text/help-"+topic+".txt")
    if e!=nil { b,_=textFiles.ReadFile("cli_text/help-help.txt") }
    fmt.Fprint(os.Stderr,string(b))
}
func printJSON(v interface{}) error {
    b,e:=json.MarshalIndent(v,"","  ")
    if e==nil { fmt.Print(string(b)) }
    return e
}
func run(args []string) error {
    cmd,raw,q,err:=parseInvocation(args)
    if err!=nil{return err}
    switch cmd {
    case "help": printHelp(q.Text);return nil
    case "version","bash-completion","fish-completion","zsh-completion":
        b,_:=textFiles.ReadFile("cli_text/"+cmd+".txt");fmt.Print(string(b));return nil
    }
    s,err:=openStore()
    if err!=nil{return err}
    switch cmd {
    case "git": return s.git(true,raw...)
    case "undo":
        n:=1
        if len(raw)>1 { printHelp("undo");return nil }
        if len(raw)==1 { var e error;n,e=strconv.Atoi(raw[0]);if e!=nil {printHelp("undo");return nil} }
        return s.git(true,"revert","--no-edit",fmt.Sprintf("HEAD~%d..",n))
    case "sync":
        if e:=s.git(true,"pull","--no-edit");e!=nil{return e}
        return s.git(true,"push")
    case "context":
        if len(raw)==0 { fmt.Println(s.Context.String());return nil }
        if len(raw)>0 && raw[0]=="none" { return s.saveContext(Query{}) }
        if len(q.IDs)>0 { return fmt.Errorf("context cannot contain IDs") }
        if q.Text!="" { return fmt.Errorf("context cannot contain text") }
        q.Notes="";q.Ignore=false
        return s.saveContext(q)
    }
