        statuses:=openStatuses
        switch cmd {
        case "show-active": statuses=[]string{"active"}
        case "show-paused": statuses=[]string{"paused"}
        case "show-resolved": statuses=[]string{"resolved"}
        case "show-templates": statuses=[]string{"template"}
        }
        tasks:=s.selectTasks(statuses,qq)
        if cmd=="show-tags" {
            tags:=map[string]bool{}
            for _,t:=range tasks { for _,tag:=range t.Tags { tags[tag]=true } }
            for tag:=range tags { fmt.Println(tag) }
            return nil
        }
        if isTTY() && cmd!="show-resolved" {
            if len(q.IDs)==0 { s.contextMessage(q) }
            return renderTasks(s,tasks,cmd=="next")
        }
        return printJSON(tasks)
    }
    return nil
}
func addTask(s *Store,q Query) error {
    if q.Text=="" && q.Template==0 { return fmt.Errorf("task description or template required") }
    s.contextMessage(q)
    qq,err:=combineQuery(q,s.Context);if err!=nil{return err}
    var t *Task
    copiedOpen:=false
    if q.Template!=0 {
        src,e:=s.task(q.Template);if e!=nil{return e}
        dup:=*src;t=&dup
        copiedOpen=src.Status!="template"
        t.UUID=newUUID();t.ID=0;t.path="";t.Status="pending";t.Resolved=time.Time{};t.Created=time.Now()
        t.Tags=append([]string{},src.Tags...)
        if q.Text!="" { t.Summary=q.Text }
        t.apply(qq)
    } else { t=createTask(qq,"pending") }
    t.ID=s.allocate(t.UUID)
    if e:=s.saveTask(t);e!=nil{return e}
    if e:=s.commit("Added "+t.label());e!=nil{return e}
    if copiedOpen { fmt.Print("\nYou've copied an open task!\nTo learn more about creating templates enter 'dstask help template'\n\n") }
    return nil
}
func templateTask(s *Store,q Query) error {
    if len(q.IDs)>0 {
        for _,id:=range q.IDs {
            t,e:=s.task(id);if e!=nil{return e}
            if e:=transition(t,"template");e!=nil{return e}
            if e:=s.saveTask(t);e!=nil{return e}
            if e:=s.commit("Changed "+t.label()+" to Template");e!=nil{return e}
        }
        return nil
    }
    if q.Text=="" { return nil }
    t:=createTask(q,"template");t.ID=s.allocate(t.UUID)
    if e:=s.saveTask(t);e!=nil{return e}
    return s.commit("Created Template "+t.label())
}
func actOnTasks(s *Store,q Query,status,verb string) error {
    if len(q.IDs)==0 { return fmt.Errorf("no ID(s) specified") }
    // Capture references as operations happen so duplicate IDs can still refer
    // to a task resolved earlier within the same command.
    captured:=map[int]*Task{}
    for _,id:=range q.IDs {
        t:=captured[id]
        if t==nil { var e error;t,e=s.task(id);if e!=nil{return e};captured[id]=t }
        if e:=transition(t,status);e!=nil{return e}
        if q.Text!="" { t.appendNote(q.Text) }
        label:=t.label()
        if e:=s.saveTask(t);e!=nil{return e}
        if e:=s.commit(verb+" "+label);e!=nil{return e}
        if status=="active" && t.Notes!="" { printNotes(t) }
    }
    return nil
}
func modifyTasks(s *Store,q Query) error {
    if !q.operations() { return fmt.Errorf("no operations specified") }
    ids:=q.IDs
    if len(ids)==0 {
        ctx:=s.Context
        if q.Ignore { ctx=Query{} }
        tasks:=s.selectTasks(openStatuses,ctx)
        if isTTY() {
            if e:=confirm(fmt.Sprintf("no IDs specified. Apply to all %d tasks in current ctx?",len(tasks)));e!=nil{return e}
        }
        for _,t:=range tasks { ids=append(ids,t.ID) }
    }
    for _,id:=range ids {
        t,e:=s.task(id);if e!=nil{return e}
        t.apply(q)
        if e:=s.saveTask(t);e!=nil{return e}
        if e:=s.commit("Modified "+t.label());e!=nil{return e}
    }
    return nil
}
func confirm(prompt string) error {
    fmt.Fprint(os.Stderr,prompt+" [y/n] ")
    var answer string
    fmt.Fscanln(os.Stdin,&answer)
    if answer!="y" { return fmt.Errorf("Aborted.") }
    return nil
}
func removeTasks(s *Store,q Query) error {
    if len(q.IDs)==0 { return fmt.Errorf("no ID(s) specified") }
    tasks:=[]*Task{}
    for _,id:=range q.IDs {
        t,e:=s.task(id);if e!=nil{return e}
        tasks=append(tasks,t);fmt.Println(t.label())
    }
    if isTTY() { if e:=confirm(fmt.Sprintf("\nThe above %d task(s) will be deleted without checking subtasks. Continue?",len(tasks)));e!=nil{return e} }
    for _,t:=range tasks {
        if e:=os.Remove(t.path);e!=nil{return e}
        delete(s.IDs,t.UUID)
        if e:=s.saveIDs();e!=nil{return e}
        if e:=s.commit("Removed: "+t.label());e!=nil{return e}
    }
    return nil
}
func printNotes(t *Task) {
    fmt.Printf("\nNotes on task %d:\n%s%s%s\n\n",t.ID,grey,t.Notes,reset)
}
func notes(s *Store,q Query) error {
    if len(q.IDs)==0 { return fmt.Errorf("no ID(s) specified") }
    // A redirected notes report is intentionally just the note body.
    if !isTTY() {
        t,e:=s.task(q.IDs[0]);if e!=nil{return e}
        fmt.Print(t.Notes);return nil
    }
    for _,id:=range q.IDs {
        t,e:=s.task(id);if e!=nil{return e}
        if q.Text!="" { t.appendNote(q.Text) } else {
            b,e:=invokeEditor([]byte(t.Notes),".md");if e!=nil{return e}
            t.Notes=string(b)
        }
        if e:=s.saveTask(t);e!=nil{return e}
        if e:=s.commit("Edit note "+t.label());e!=nil{return e}
    }
    return nil
}
func invokeEditor(content []byte,suffix string)([]byte,error) {
    f,e:=os.CreateTemp("","dstask-*"+suffix);if e!=nil{return nil,e}
    name:=f.Name();defer os.Remove(name)
    if _,e=f.Write(content);e!=nil { f.Close();return nil,e };f.Close()
    editor:=os.Getenv("EDITOR")
    if editor=="" { editor="vim" }
    parts:=strings.Fields(editor)
    cmd:=exec.Command(parts[0],append(parts[1:],name)...)
    cmd.Stdin=os.Stdin;cmd.Stdout=os.Stdout;cmd.Stderr=os.Stderr
    if e:=cmd.Run();e!=nil{return nil,fmt.Errorf("Failed to run editor: %v",e)}
    return os.ReadFile(name)
}
func editTasks(s *Store,q Query) error {
    if len(q.IDs)==0 { return fmt.Errorf("no ID(s) specified") }
    for _,id:=range q.IDs {
        t,e:=s.task(id);if e!=nil{return e}
        content,e:=invokeEditor(taskYAML(t,true),".yml");if e!=nil{return e}
        changed,e:=readTaskYAML(content);if e!=nil{return e}
        status:=changed.Status
        if status=="" { status=t.Status }
        // An edit can explicitly return a task to its initial state as well as
        // change its summary and metadata.
        if status!=t.Status {
            if e:=transition(t,status);e!=nil{return e}
        }
        changed.UUID=t.UUID;changed.ID=t.ID;changed.path=t.path;changed.Status=status
        *t=*changed
        label:=t.label()
        if e:=s.saveTask(t);e!=nil{return e}
        if e:=s.commit("Edited "+label);e!=nil{return e}
    }
    return nil
}
var urlPattern=regexp.MustCompile(`(?i)(?:https?|ftp)://[^\s<>"\[\]]+`)
func openTasks(s *Store,q Query) error {
    if len(q.IDs)==0 { return fmt.Errorf("no ID(s) specified") }
    for _,id:=range q.IDs {
        t,e:=s.task(id);if e!=nil{return e}
        urls:=urlPattern.FindAllString(t.Summary+"\n"+t.Notes,-1)
        if len(urls)==0 { return fmt.Errorf("no URLs found in task %d",id) }
        seen:=map[string]bool{}
        for _,u:=range urls {
            u=strings.TrimRight(u,".,;)")
            if seen[u] { continue };seen[u]=true
            c:=exec.Command("xdg-open",u);c.Stdin=os.Stdin;c.Stdout=os.Stdout;c.Stderr=os.Stderr
            if e:=c.Run();e!=nil{return e}
        }
    }
    return nil
}

func completions(s *Store,args []string) error {
    words:=[]string{}
    if len(args)>0 { words=args[1:] }
    partial:=""
    if len(words)>0 { partial=words[len(words)-1] }
    c:=""
    for _,w:=range words { if knownCommand(w) { c=w;break } }
    opts:=[]string{}
    if c=="" || c=="help" {
        for _,name:=range commandNames { if name!=c { opts=append(opts,name) } }
    }
    if c!="help" {
        opts=append(opts,"P0","P1","P2","P3")
        q,e:=combineQuery(Query{},s.Context);if e!=nil{return e}
        tasks:=s.selectTasks(openStatuses,q)
        for _,p:=range projectsOf(tasks) { opts=append(opts,"project:"+p.Name,"-project:"+p.Name) }
        tags:=map[string]bool{}
        for _,t:=range tasks { for _,tag:=range t.Tags { tags[tag]=true } }
        for tag:=range tags { opts=append(opts,"+"+tag,"-"+tag) }
    }
    for _,v:=range opts { if strings.HasPrefix(v,partial) { fmt.Println(v) } }
    return nil
}

