    st,err:=os.Stat(root)
    if os.IsNotExist(err) {
        if e:=os.MkdirAll(root,0700);e!=nil { return nil,e }
        if e:=s.git(false,"init");e!=nil { return nil,e }
        fmt.Print("\nAdd a remote repository with:\n\n\tdstask git remote add origin <repo>\n\n")
    } else if err!=nil { return nil,err } else if !st.IsDir() {
        return nil,fmt.Errorf("Failed to open %s for reading: ",filepath.Join(s.Meta,"state.bin"))
    }
    if err:=os.Mkdir(s.Meta,0700);err!=nil && !os.IsExist(err) { return nil,fmt.Errorf("Failed to create directory in git repository") }
    if b,e:=os.ReadFile(filepath.Join(s.Meta,"state.bin"));e==nil { _=json.Unmarshal(b,&s.Context) }
    if b,e:=os.ReadFile(filepath.Join(s.Meta,"ids.bin"));e==nil { _=json.Unmarshal(b,&s.IDs) }
    if s.IDs==nil { s.IDs=make(map[string]int) }
    if ctx:=os.Getenv("DSTASK_CONTEXT");ctx!="" {
        q,e:=parseQuery(strings.Fields(ctx))
        if e!=nil { return nil,e }
        s.Context=q
    }
    return s,nil
}
func (s *Store) load() error {
    s.Tasks=[]*Task{}
    alive:=make(map[string]bool)
    for _,status:=range []string{"active","pending","paused","template","resolved"} {
        files,_:=filepath.Glob(filepath.Join(s.Root,status,"*.yml"))
        for _,f:=range files {
            info,e:=os.Stat(f)
            if e!=nil || info.IsDir() { continue }
            b,e:=os.ReadFile(f)
            if e!=nil { return e }
            t,e:=readTaskYAML(b)
            if e!=nil { return fmt.Errorf("%s",e) }
            uuid:=strings.TrimSuffix(filepath.Base(f),".yml")
            t.UUID=uuid
            t.Status=status
            t.path=f
            if status!="resolved" { alive[uuid]=true }
            s.Tasks=append(s.Tasks,t)
        }
    }
    for u:=range s.IDs { if !alive[u] { delete(s.IDs,u) } }
    for _,t:=range s.Tasks {
        if t.Status!="resolved" {
            if id,ok:=s.IDs[t.UUID];ok { t.ID=id } else { t.ID=s.allocate(t.UUID) }
        }
    }
    return s.saveIDs()
}
func (s *Store) allocate(uuid string) int {
    used:=make(map[int]bool)
    for _,n:=range s.IDs { used[n]=true }
    n:=1
    for used[n] { n++ }
    s.IDs[uuid]=n
    return n
}
func (s *Store) saveIDs() error {
    b,e:=json.Marshal(s.IDs)
    if e!=nil { return e }
    return os.WriteFile(filepath.Join(s.Meta,"ids.bin"),b,0600)
}
func (s *Store) saveContext(q Query) error {
    b,e:=json.Marshal(q)
    if e!=nil { return e }
    return os.WriteFile(filepath.Join(s.Meta,"state.bin"),b,0600)
}
func (s *Store) task(id int) (*Task,error) {
    for _,t:=range s.Tasks { if t.ID==id && id!=0 && t.Status!="resolved" { return t,nil } }
    return nil,fmt.Errorf("no open task with ID %d exists",id)
}
func (s *Store) saveTask(t *Task) error {
    if t.UUID=="" { t.UUID=newUUID() }
    if t.Status!="resolved" && t.ID==0 { t.ID=s.allocate(t.UUID) }
    newpath:=filepath.Join(s.Root,t.Status,t.UUID+".yml")
    if e:=os.MkdirAll(filepath.Dir(newpath),0700);e!=nil { return e }
    if e:=os.WriteFile(newpath,taskYAML(t,false),0644);e!=nil { return e }
    if t.path!="" && t.path!=newpath { if e:=os.Remove(t.path);e!=nil && !os.IsNotExist(e) { return e } }
    t.path=newpath
    if t.Status=="resolved" { delete(s.IDs,t.UUID);t.ID=0 }
    return s.saveIDs()
}
func (s *Store) git(genericError bool,args ...string) error {
    cmd:=exec.Command("git",append([]string{"-C",s.Root},args...)...)
    cmd.Stdin=os.Stdin
    cmd.Stdout=os.Stdout
    cmd.Stderr=os.Stderr
    err:=cmd.Run()
    if err!=nil && genericError { return fmt.Errorf("Failed to run git cmd.") }
    return err
}
func (s *Store) commit(message string) error {
    fmt.Print("\n"+message+"\n"+grey)
    cmd:=exec.Command("git","-C",s.Root,"add","--all")
    cmd.Stderr=os.Stderr
    if e:=cmd.Run();e!=nil { return fmt.Errorf("error: failed to stage changes: %v",e) }
    diff:=exec.Command("git","-C",s.Root,"diff","--cached","--quiet")
    if diff.Run()==nil {
        fmt.Print("No changes detected\n"+reset)
        return nil
    }
    if e:=s.git(false,"commit","-m",message);e!=nil { return fmt.Errorf("error: failed to commit changes: %v",e) }
    fmt.Print(reset)
    return nil
}
func (s *Store) selectTasks(statuses []string,q Query) []*Task {
    out:=[]*Task{}
    for _,t:=range s.Tasks { if containsString(statuses,t.Status) && t.matches(q) { out=append(out,t) } }
    sortTasks(out)
