func notes(s *Store,q Query) error {
    if len(q.IDs)==0 { return fmt.Errorf("no ID(s) specified") }
    // A redirected notes report is intentionally just the note body.
    if !isTTY() {
        t,e:=s.task(q.IDs[0]);if e!=nil{return e}
        fmt.Print(t.Notes);return nil
    }
    for _,id:=range q.IDs {
        t,e:=s.task(id);if e!=nil{return e}
        if q.Text!="" { t.appendNote(q.Text) } else {
            b,e:=invokeEditor([]byte(t.Notes),".md");if e!=nil{return e}
            t.Notes=string(b)
