}
func crop(s string,n int)string {
    if n<=0{return ""}
    s=strings.SplitN(s,"\n",2)[0]
    r:=[]rune(s)
    if len(r)<=n{return s}
    n-- // reserve the last display column when wrapping a long value
    if n<1{return ""}
    first:=string(r[:n])
    if i:=strings.LastIndexAny(first," \t");i>0 { first=first[:i] }
    return strings.TrimRight(first," ")
}
func textWidth(s string)int {
    mx:=0
    for _,line:=range strings.Split(s,"\n") { if width(line)>mx {mx=width(line)} }
    return mx
}
type tableRow struct { Cells []string; FG,BG int }
func displayTable(headers []string,rows []tableRow) {
    widths:=make([]int,len(headers))
    for i,h:=range headers{widths[i]=width(h)}
    for _,r:=range rows { for i,v:=range r.Cells {if w:=textWidth(v);w>widths[i]{widths[i]=w}} }
    used:=2*(len(headers)-1)
    for _,w:=range widths{used+=w}
    if used>terminalWidth() { widths[len(widths)-1]-=used-terminalWidth();if widths[len(widths)-1]<1{widths[len(widths)-1]=1} }
    h:=[]string{}
    for i,v:=range headers {h=append(h,pad(crop(v,widths[i]),widths[i]))}
