}
func dueDisplay(t time.Time)string {
    if t.IsZero(){return ""}
    now:=time.Now();today:=time.Date(now.Year(),now.Month(),now.Day(),0,0,0,0,time.Local)
    delta:=int(t.Sub(today).Hours()/24)
    if t.Year()==today.Year() && t.YearDay()==today.YearDay(){return "today"}
    if delta==1 {return "tomorrow"}
    if delta==-1 {return "yesterday"}
    if delta>1 && delta<7 {return t.Format("Mon _2")}
