        add("ID",strconv.Itoa(t.ID));add("Priority",t.Priority);add("Summary",t.Summary);add("Status",t.Status)
        add("Project",t.Project);add("Tags",strings.Join(t.Tags,", "));add("UUID",t.UUID);add("Created",t.Created.String())
        if !t.Resolved.IsZero(){add("Resolved",t.Resolved.String())}
        if !t.Due.IsZero(){add("Due",t.Due.String())}
        displayTable([]string{"Name","Value"},rows)
        if t.Notes!="" {printNotes(t);fmt.Println()}
    } else {
        if truncate && len(tasks)>15{tasks=tasks[:15]}
        headers:=[]string{"ID","Priority","Tags","Due","Project","Summary"}
        ws:=[]int{2,8,4,3,7,7}
        cells:=[][]string{}
        notes:=[]string{}
        for _,t:=range tasks {
            note:=previewNote(t)
            row:=[]string{strconv.Itoa(t.ID),t.Priority,strings.Join(t.Tags," "),dueDisplay(t.Due),t.Project,t.Summary}
            for i,v:=range row {
                w:=textWidth(v)
                if i==5 && note!="" {w=textWidth(v+" "+note+"  ")}
                if w>ws[i]{ws[i]=w}
            }
            cells=append(cells,row);notes=append(notes,note)
        }
        total:=10
        for _,w:=range ws{total+=w}
        if total>terminalWidth(){ws[5]-=total-terminalWidth();if ws[5]<1{ws[5]=1}}
        hh:=[]string{}
        for i,h:=range headers{hh=append(hh,pad(crop(h,ws[i]),ws[i]))}
        fmt.Println(style(250,232,4)+strings.Join(hh,"  ")+reset)
        for n,row:=range cells {
            fg,bg:=priorityColors(tasks[n],n)
            line:=""
            for i:=0;i<5;i++{line+=pad(crop(row[i],ws[i]),ws[i])+"  "}
            text:=row[5]
            note:=notes[n]
            if note!="" && !strings.Contains(text,"\n") && width(text)+1<ws[5] {
                remaining:=ws[5]-width(text)
                extra:=pad(crop(" "+note,remaining),remaining)
                text+= "\x1b[38;5;240m"+extra+fmt.Sprintf("\x1b[38;5;%dm",fg)
            } else {text=pad(crop(text,ws[5]),ws[5])}
            fmt.Println(style(fg,bg,0)+line+text+reset)
        }
        if len(tasks)<len(all){fmt.Printf("\n%d/%d tasks shown.\n",len(tasks),len(all))}else{fmt.Printf("\n%d tasks.\n",len(tasks))}
    }
    shown:=map[string]bool{}
    for _,t:=range all{shown[t.UUID]=true}
    count:=0
    for _,t:=range s.Tasks{if containsString(openStatuses,t.Status) && t.Priority=="P0" && !shown[t.UUID]{count++}}
    if count>0{fmt.Printf("\x1b[38;5;160m%d critical task(s) outside this context! Use `dstask -- P0` to see them.\x1b[0m\n",count)}
    return nil
}
func renderProjects(ps []*Project)error {
    rows:=[]tableRow{}
    for _,p:=range ps {
