func TestArgumentGrammar(t *testing.T) {
    cmd,_,q,e:=parseInvocation([]string{"1","start","2","P1","Summary","project:Example","/","note","+work"})
    if e!=nil {t.Fatal(e)}
    if cmd!="start" || !reflect.DeepEqual(q.IDs,[]int{1,2}) || q.Priority!="P1" || q.Project!="example" || q.Text!="Summary" || q.Notes!="note +work" {t.Fatalf("unexpected query: %#v (%s)",q,cmd)}
    _,_,q,e=parseInvocation([]string{"add","42","Answer","P1","P3","project:one","project:two"})
    if e!=nil || q.Text!="Answer P3 project:two" || q.Priority!="P1" || q.Project!="one" {t.Fatalf("unexpected repeated properties: %#v %v",q,e)}
    cmd,_,q,e=parseInvocation([]string{"eat","some","add","bananas","--"})
    if e!=nil || cmd!="add" || q.Text!="eat some bananas" || !q.Ignore {t.Fatalf("unexpected command extraction: %s %#v",cmd,q)}
}

func TestContextMerge(t *testing.T) {
    ctx,_:=parseQuery([]string{"+Work","-low","project:example","P1"})
    q,_:=parseQuery([]string{"task","+home"})
    got,e:=combineQuery(q,ctx)
    if e!=nil || got.Text!="task" || got.Priority!="P1" || !reflect.DeepEqual(got.Tags,[]string{"home","work"}) {t.Fatalf("bad merge: %#v %v",got,e)}
    q.Priority="P0"
