    q.Ignore=true
    if got,e=combineQuery(q,ctx);e!=nil || got.Priority!="P0" {t.Fatalf("ignore context: %#v %v",got,e)}
    if ctx.String()!="+work -low project:example P1" {t.Fatal(ctx.String())}
}

func TestDates(t *testing.T) {
    date,e:=parseDue("2024-02-29")
    if e!=nil || date.Format("2006-01-02")!="2024-02-29" {t.Fatal(date,e)}
    for _,invalid:=range []string{"2025-02-29","2026-1-01","none","next-week","32",""} {
