func TestYAMLRoundTrips(t *testing.T) {
    examples:=[]string{"", "simple", "x: y", "true", "it's quoted", "a\nb", "\nabc", "abc\n", "abc\n\n", "\n", "\n\n", " spaced ", strings.Repeat("word ",40), "中文 "+strings.Repeat("任务 ",40)}
    for _,v:=range examples {
        original:=createTask(Query{Text:v,Notes:v},"pending")
        data:=taskYAML(original,false)
        parsed,e:=readTaskYAML(data)
        if e!=nil {t.Fatalf("parse %q: %v\n%s",v,e,data)}
        if parsed.Summary!=v || parsed.Notes!=v {t.Fatalf("round trip %q -> %q / %q\n%s",v,parsed.Summary,parsed.Notes,data)}
    }
}
func TestSearchAndChanges(t *testing.T) {
    task:=createTask(Query{Text:"alpha task",Notes:"line one\nline two",Tags:[]string{"a","b"}},"pending")
    if !task.matches(Query{Text:"taskline"}) {t.Fatal("search must span summary and notes")}
    task.apply(Query{Tags:[]string{"c"},AntiTags:[]string{"a"},Priority:"P1"})
    if !reflect.DeepEqual(task.Tags,[]string{"b","c"}) || task.Notes!="line one\nline two\n" {t.Fatalf("bad modification: %#v",task)}
    if transition(task,"paused")==nil {t.Fatal("pending -> paused should fail")}
    if e:=transition(task,"active");e!=nil {t.Fatal(e)}
    if e:=transition(task,"paused");e!=nil {t.Fatal(e)}
    if e:=transition(task,"resolved");e!=nil || task.Resolved.IsZero() {t.Fatal(e)}
}
func TestIDReuseAndRestoration(t *testing.T) {
    root:=t.TempDir()
    meta:=filepath.Join(root,".git","dstask")
    if e:=os.MkdirAll(meta,0700);e!=nil {t.Fatal(e)}
    store:=&Store{Root:root,Meta:meta,IDs:make(map[string]int)}
    a:=createTask(Query{Text:"a"},"pending")
    a.Created=time.Date(2020,1,1,0,0,0,0,time.UTC)
    if e:=store.saveTask(a);e!=nil {t.Fatal(e)}
    if e:=store.load(false);e!=nil {t.Fatal(e)}
    if a.ID!=1 {t.Fatal(a.ID)}
    oldData:=taskYAML(a,false)
    os.Remove(a.path)
    store.load(false)
    os.WriteFile(a.path,oldData,0644)
    store.load(false)
    if store.Tasks[0].ID!=1 {t.Fatal("restored task lost its ID")}
    os.Remove(a.path)
    store.load(false)
    b:=createTask(Query{Text:"b"},"pending")
    if e:=store.saveTask(b);e!=nil {t.Fatal(e)}
    if b.ID!=1 {t.Fatal("lowest vacant ID not reused")}
    os.WriteFile(a.path,oldData,0644)
    if e:=store.load(false);e!=nil {t.Fatal(e)}
    ids:=map[int]bool{}
    for _,task:=range store.Tasks {if ids[task.ID] {t.Fatal("ID collision")};ids[task.ID]=true}
}
